/* Only app assets; no clinical input, external sources or account pages are cached. */
const VERSION='pediatric-v0.5-20261027-a',ASSETS=['index.html','style.css','infusion.css','calculator.css','infusion.js','clinical-data.js','clinical-core.js','clinical-ui.js','calculator.js','app-v3.js','manifest.webmanifest','icon.svg','offline.js'];
const base=new URL('./',self.location.href),urls=ASSETS.map(p=>new URL(p,base).href);
self.addEventListener('install',e=>e.waitUntil((async()=>{const cache=await caches.open(VERSION);for(const url of urls){const r=await fetch(new Request(url,{cache:'reload',credentials:'same-origin'}));if(!r.ok||r.redirected)throw Error('App asset unavailable');const type=r.headers.get('content-type')||'';if(url.endsWith('.js')&&!/javascript/.test(type))throw Error('Invalid script response');if(url.endsWith('index.html')&&!(await r.clone().text()).includes('clinical-data.js'))throw Error('Not the app document');await cache.put(url,r)}})()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('pediatric-')&&key!==VERSION)await caches.delete(key);await self.clients.claim()})()));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==base.origin||!u.href.startsWith(base.href))return;if(e.request.mode==='navigate'&&(u.pathname===base.pathname||u.pathname===new URL('index.html',base).pathname)){e.respondWith((async()=>{const c=await caches.open(VERSION);return await c.match(new URL('index.html',base).href)||fetch(e.request)})());return}if(urls.includes(u.href))e.respondWith((async()=>{const c=await caches.open(VERSION);return await c.match(u.href)||fetch(e.request)})())});
self.addEventListener('message',e=>{if(e.data?.type==='ACTIVATE')self.skipWaiting();if(e.data?.type==='STATUS')e.waitUntil((async()=>{const c=await caches.open(VERSION);const ready=(await Promise.all(urls.map(url=>c.match(url)))).every(Boolean);e.source?.postMessage({type:'OFFLINE_STATUS',version:VERSION,ready})})())});
